    A = [0] + list(map(int, input().split()))

    children = [[] for _ in range(N + 1)]
    indeg = [0] * (N + 1)

    for i in range(1, N + 1):
        children[A[i]].append(i)
        indeg[A[i]] += 1

    q = deque(i for i in range(1, N + 1) if indeg[i] == 0)
    order = []

    while q:
        v = q.popleft()
        order.append(v)
        p = A[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    in_cycle = [False] * (N + 1)
    for i in range(1, N + 1):
        if indeg[i] > 0:
            in_cycle[i] = True

    dp = [None] * (N + 1)

    for v in order:
        prod = [1] * (M + 1)

        for ch in children[v]:
            arr = dp[ch]
            for k in range(1, M + 1):
                prod[k] = prod[k] * arr[k] % MOD

        arr = [0] * (M + 1)
        acc = 0
        for k in range(1, M + 1):
            acc += prod[k]
            acc %= MOD
            arr[k] = acc

        dp[v] = arr

    ans = 1
    seen = [False] * (N + 1)

    for i in range(1, N + 1):
        if not in_cycle[i] or seen[i]:
            continue

        cycle = []
        v = i
        while not seen[v]:
            seen[v] = True
            cycle.append(v)
            v = A[v]

        ways = [1] * (M + 1)

        for c in cycle:
            for ch in children[c]:
